// Package main 是图书管理系统后端服务入口。
package main

import (
	"log"
	"net/http"

	"lms/backend/internal/config"
	"lms/backend/internal/httpapi"
	"lms/backend/internal/service"
	"lms/backend/internal/store"
)

func main() {
	cfg := config.Load()

	st, err := store.New(cfg.DBPath)
	if err != nil {
		log.Fatalf("初始化数据库失败: %v", err)
	}
	defer st.Close()

	svc := service.New(st)
	srv := httpapi.New(svc, cfg.TokenSecret)

	log.Printf("图书管理系统后端已启动，监听 %s（数据库：%s）", cfg.Addr, cfg.DBPath)
	if err := http.ListenAndServe(cfg.Addr, srv.Handler()); err != nil {
		log.Fatalf("服务退出: %v", err)
	}
}

// Package config 负责运行配置：监听地址、数据文件路径、令牌密钥等。
package config

import (
	"os"
	"path"
)

// Config 保存后端运行参数。
type Config struct {
	Addr       string // HTTP 监听地址
	DBPath     string // SQLite 数据库路径
	TokenSecret []byte // 登录令牌 HMAC 密钥
}

// appDir 返回可执行文件（或开发时项目）所在目录，保证数据库与程序同目录、便于便携。
func appDir() string {
	if exe, err := os.Executable(); err == nil {
		return path.Dir(exe)
	}
	return "."
}

// Load 从环境变量读取配置，未设置时使用默认值。
func Load() *Config {
	addr := os.Getenv("LMS_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8765"
	}
	dbPath := os.Getenv("LMS_DB")
	if dbPath == "" {
		dbPath = path.Join(appDir(), "library_data.db")
	}
	secret := os.Getenv("LMS_SECRET")
	if secret == "" {
		secret = "lms-local-default-secret-change-me"
	}
	return &Config{
		Addr:        addr,
		DBPath:      dbPath,
		TokenSecret: []byte(secret),
	}
}

package httpapi

import (
	"net/http"
	"time"
)

type loginReq struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

type loginResp struct {
	Token    string `json:"token"`
	Role     string `json:"role"`
	Username string `json:"username"`
	RealName string `json:"realName"`
	ReaderNo string `json:"readerNo"`
}

func (s *Server) login(w http.ResponseWriter, r *http.Request) {
	var req loginReq
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "请求格式错误")
		return
	}
	u, err := s.svc.Login(req.Username, req.Password)
	if err != nil {
		fail(w, err)
		return
	}
	token, err := signToken(claims{
		UID: u.ID, Username: u.Username, Role: u.Role, RealName: u.RealName,
		Exp: time.Now().Add(24 * time.Hour).Unix(),
	}, s.secret)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "令牌签发失败")
		return
	}
	resp := loginResp{Token: token, Role: u.Role, Username: u.Username, RealName: u.RealName}
	if u.Role == "reader" {
		if rd, err := s.svc.MyReader(u); err == nil {
			resp.ReaderNo = rd.ReaderNo
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

